import requests

url = "https://api.example.com/v1/users"

payload = {
    "name": "Ada",
    "age": 36,
    "active": True
}
headers = {
    "accept": "application/json",
    "content-type": "application/json"
}

response = requests.post(url, json=payload, headers=headers)

print(response.text)
